WITH matched_keys AS (SELECT device FROM sessions INTERSECT ALL SELECT device FROM sessions WHERE browser IN ('Firefox', 'Chrome')), reconciled AS (SELECT s.* FROM sessions s INNER JOIN matched_keys k ON s.device = k.device), valid AS (SELECT id, customer_id, device, browser, started_at, country, CASE WHEN device = 'mobile' THEN 1 ELSE 0 END AS is_mobile FROM reconciled WHERE started_at > TO_TIMESTAMP('2023-08-19 03:00:00') AND customer_id IS NOT NULL AND country IN ('US', 'UK', 'JP')), joined AS (SELECT src.*, b.city FROM valid src LEFT JOIN customers b ON src.customer_id = b.id), kept AS (SELECT s.* FROM joined s WHERE EXISTS (SELECT 1 FROM web_events x WHERE x.session_id = s.id AND x.event_time <= s.started_at)), joined_sessions AS (SELECT e.*, d.credit_limit, d.country AS customer_country, d.name FROM kept e LEFT JOIN customers d ON e.customer_id = d.id), valid_sessions AS (SELECT *, COALESCE(city, 'unassigned') AS city_filled, COALESCE(country, 'OTHER') AS resolved_country FROM joined_sessions WHERE country IS NOT NULL) SELECT s.id, s.customer_id, s.device, s.started_at, s.country, s.is_mobile, s.city, s.name, s.city_filled, (SELECT MIN(t2.monthly_fee) FROM subscriptions t2 WHERE t2.customer_id = s.customer_id) AS min_subscription_monthly_fee FROM valid_sessions s ORDER BY started_at NULLS FIRST
